SELECT ('00000000-0000-7000-8000-0000000000' || lpad(n::text,2,'0'))::uuid, 'n8n_braco', 'venda:' || lpad(n::text,32,'0'), encode(sha256(convert_to('venda:' || lpad(n::text,32,'0'),'UTF8')),'hex'), repeat('a',64), 'venda', 'op@exemplo.test',
  '11111111-1111-7111-8111-111111111111', 'chatOLD' || lpad(n::text,3,'0'), 'a1b2c3d4e5f6a1b2c3d4e5f6', 1,1,1,1, 'duble', 'crit_v1', 'baixa', 'encerrado', now() - make_interval(days => d + 1), 'sem_venda', now() - make_interval(days => d + 1), now() - make_interval(days => d), NULL
FROM (VALUES (10, 15), (11, 10), (12, 400)) v(n, d);
SELECT a.atendimento_id, 1, 'cliente', 1, decode('000000000000000000000000','hex'), decode(repeat('ab',20),'hex'), a.iniciado_em, a.iniciado_em + interval '30 days' FROM ia.atendimento a WHERE chat_id LIKE 'chatOLD%';
SELECT a.atendimento_id, 'digitacao', 1, decode('000000000000000000000000','hex'), decode(repeat('ab',20),'hex'), a.iniciado_em, a.iniciado_em + interval '7 days' FROM ia.atendimento a WHERE chat_id LIKE 'chatOLD%';
