INSERT INTO ia.agendamento (atendimento_id, pessoa_id, chat_id, entrada, seq, msg_chave, texto_hash, retoma_fase, chave_logica, idem_key, pedido_em, criado_em) SELECT atendimento_id, pessoa_id, chat_id, 'pausa_ia', 1, 'cg:0123456789abcdef01234567:4444444444444444', repeat('a',64), 'E4', 'agenda:' || atendimento_id || ':1', encode(sha256(convert_to('agenda:' || atendimento_id || ':1','UTF8')),'hex'), iniciado_em, iniciado_em FROM ia.atendimento WHERE chat_id='chatOLD012';
